package com.bank.rankedroster;

import java.util.*;
import java.util.logging.*;

public class TreeSetDemo {
    private static final Logger log = Logger.getLogger("RankedRoster");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", 1000000),
            new Employee("Amit", 800000),
            new Employee("Priya", 800000));  // same salary as Amit → must NOT be lost
        RosterService service = new RosterService();

        service.sortedBySalary(staff).forEach(e ->
            log.info(() -> e.getName() + " : " + e.getSalary()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/RosterService.java ───
class RosterService {
    TreeSet<Employee> sortedBySalary(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.toCollection(
                () -> new TreeSet<>(
                    Comparator.comparingDouble(Employee::getSalary)   // sort by salary
                        .thenComparing(Employee::getName))));          // tie-break → keep ties
    }
}
